package com.fadlurahmanfdev.crypto_vault.model

/**
 * Result of an AES encryption.
 *
 * @property encryptedBytes Ciphertext. For GCM it includes the authentication tag.
 * @property ivBytes Initialization vector generated by the cipher. Required for decryption; not secret.
 */
data class EncryptedData(
    val encryptedBytes: ByteArray,
    val ivBytes: ByteArray,
) {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as EncryptedData

        if (!encryptedBytes.contentEquals(other.encryptedBytes)) return false
        if (!ivBytes.contentEquals(other.ivBytes)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = encryptedBytes.contentHashCode()
        result = 31 * result + ivBytes.contentHashCode()
        return result
    }
}
